// 20261016_120000_seed_sources with "Monitor on" unticked: the first run is by hand, then the
// monitors are switched on (docs/STATUS.md). Later sources are added in the admin.

export type SourceSeed = {
  key: string
  name: string
  /** The employer's ROR ID (the unit's, where ROR has one). */
  rorId: string | null
  kind: 'rss' | 'api' | 'page' | 'manual'
  apiFormat: 'greenhouse' | 'lever' | 'smartrecruiters' | null
  url: string
  postingPattern: string | null
  schedule: 'daily' | 'weekly' | 'monthly'
  termsUrl: string | null
  termsAutomation: 'not-stated' | 'allows' | 'forbids' | 'not-found'
  termsNote: string | null
  notes: string
}

